function readStatePath(
  state: unknown,
  statePath: string,
): unknown {
  let current:
    unknown = state;

  for (
    const segment of
    statePath.split(".")
  ) {
    if (
      typeof current !==
        "object" ||
      current === null
    ) {
      return undefined;
    }

    current =
      (
        current as
          Record<
            string,
            unknown
          >
      )[segment];
  }

  return current;
}

const isApplicationMenuEnabled:
  MenuVisibilityResolver = (
    menuID,
    context,
  ) => {
    const rule =
      menuFeatureRules[
        menuID
      ];

    if (!rule) {
      return true;
    }

    const authenticationMethod =
      context.authenticationMethod ??
      "unset";

    if (
      rule.authInclude &&
      !rule.authInclude.includes(
        authenticationMethod,
      )
    ) {
      return false;
    }

    if (
      rule.authExclude?.includes(
        authenticationMethod,
      )
    ) {
      return false;
    }

    return true;
  };

const isApplicationTabEnabled:
  TabVisibilityResolver = (
    featureID,
    context,
  ) => {
    const rule =
      tabFeatureRules[
        featureID
      ];

    if (!rule) {
      return true;
    }

    if (
      rule.type ===
      "stateEquals"
    ) {
      if (
        !rule.statePath
      ) {
        return false;
      }

      return (
        String(
          readStatePath(
            context.state,
            rule.statePath,
          ),
        ) ===
        rule.value
      );
    }

    return true;
  };

